using System;using System.IO;using System.Linq;using UnityEngine;using EternalSteam;using EternalSteam.OpenWorld;using Newtonsoft.Json.Linq;
public static class VerifyHud07Edges{
const string Root="Docs/Measurements/2026-10-02-hud-07/";
static CanvasWorldHud H(){if(!Application.isPlaying||!(Environment.GetEnvironmentVariable("ETERNAL_STEAM_SAVE_TEST_ROOT")??"").Contains("hud-07"))throw new Exception("Isolated Play required");return UnityEngine.Object.FindFirstObjectByType<CanvasWorldHud>();}
public static string LongNames(){var h=H();var v=h.Sandbox.RailwayHud.GetComponent<RailwayOverview>();var n=h.Sandbox.Content.Railway.Network;var snapshot=n.Capture();foreach(var label in snapshot.baseLabels)label.name=string.Concat(Enumerable.Repeat("아주 긴 기지 이름 검증 ",6));snapshot.routes[0].name="장거리 화물 운송과 방어를 담당하는 긴 노선 이름 검증";n.Restore(snapshot);h.Groups.Select(true);v.Execute("open");v.Apply();v.Rows[0].onClick.Invoke();v.Execute("cargo");var rail=v.Railway;rail.Load.SetTextWithoutNotify("1000");rail.Unload.SetTextWithoutNotify("0");if(!rail.CanExecute("configure",out var why))throw new Exception("Maximum quantity rejected: "+why);rail.Load.SetTextWithoutNotify("1001");if(rail.CanExecute("configure",out _))throw new Exception("Above maximum accepted");rail.Load.SetTextWithoutNotify("7");File.WriteAllText(Root+"edge-quantity.json",new JObject{{"maximum1000Accepted",true},{"aboveMaximumRejected",true},{"longNamesApplied",true}}.ToString());return "Maximum and above-maximum validated; long names active";}
public static string BaseLoss(){var h=H();var c=h.Sandbox.Content;var a=h.BaseResources;a.Refresh();var lost=c.Bases.Bases.Values.First(b=>!ReferenceEquals(b.Nexus,c.MainBase));int index=Array.FindIndex(a.Rows,r=>r.BaseId==lost.Id);if(index<0)throw new Exception("Sub-base row missing");a.Toggle(index);if(a.ExpandedBaseId!=lost.Id)throw new Exception("Base expansion failed");c.GroundWorld.Remove(lost.Nexus.Id);c.Bases.Refresh();a.Refresh();if(a.ExpandedBaseId!=null||a.Rows.Any(r=>r.Root.activeSelf&&r.BaseId==lost.Id))throw new Exception("Lost base remains expanded");File.WriteAllText(Root+"base-loss.json",new JObject{{"result","PASS"},{"staleExpandedBaseCleared",true},{"removedRowHidden",true}}.ToString());return "Expanded sub-base loss handled";}
public static string NativeState(){var h=H();return new JObject{{"construction",h.Groups.ConstructionSelected},{"transitioning",h.Groups.Transitioning}}.ToString();}}
